#!/bin/bash -e
#
# Run this script from a directory containing a package.json to fetch as many
# of its dependencies as possible from LOCKED_NODE_MODULES
#

source $(dirname $0)/../gonk/gnutools.sh
SILK_SDK_GLUE=$(readlink -f $(dirname $0)/../sdk/glue)

LOCKED_NODE_MODULES=$(dirname $0)/node_modules

if [[ ! -d $LOCKED_NODE_MODULES ]]; then
  echo Warning: $LOCKED_NODE_MODULES does not exist, exiting.
  exit 0
fi

LIST_REMOTE_DEPS=$(dirname $0)/list_remote_deps.js

mkdir -p node_modules/
if [[ ! -f node_modules/.ok ]]; then
  echo "Fetching node_modules from $LOCKED_NODE_MODULES:"
  for p in $($LIST_REMOTE_DEPS package.json | sort -u); do

    echo -n " * $p "

    # TODO: Remove this block once the SDK is published
    if [[ $p = silk-sdk-glue ]]; then
      echo "(linked from $SILK_SDK_GLUE)"
      rsync -qav $SILK_SDK_GLUE/ node_modules/$p
      chmod -w node_modules/$p/{debug,watch,.eslintrc,Gruntfile.js}
    elif [[ ! -d $LOCKED_NODE_MODULES/$p ]]; then
      echo MISSING
    else
      rsync -qav $LOCKED_NODE_MODULES/$p node_modules/
      echo
    fi
  done
  rsync -qav $LOCKED_NODE_MODULES/.bin node_modules/
  touch node_modules/.ok
else
  # TODO: Remove this block once the SDK is published
  if [[ -d node_modules/silk-sdk-glue ]]; then
    echo "(refresh from $SILK_SDK_GLUE)"
    rsync -qav $SILK_SDK_GLUE/ node_modules/silk-sdk-glue
    chmod -w node_modules/silk-sdk-glue/{debug,watch,.eslintrc,Gruntfile.js}
  fi
fi
